"""
Tests for T1: Create book endpoint (POST /books)
"""
import json
import subprocess
import time
import requests
import sys
import os

# Use the local app.py
BASE_URL = "http://127.0.0.1:8000"


def start_server():
    """Start the book server."""
    # Start the server in a subprocess
    proc = subprocess.Popen([
        sys.executable, '/workspace/app.py'
    ], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    # Wait for server to start
    time.sleep(2)
    return proc


def stop_server(proc):
    """Stop the server subprocess."""
    proc.terminate()
    proc.wait(timeout=5)


def run_test(scenario_name, expected_status, expected_body_contains=None, 
             expected_error_message=None, json_body=None, 
             query_params=None):
    """
    Run a single test scenario.

    Returns (success, result_dict)
    """
    # Start server if needed
    global proc
    if proc is None:
        proc = start_server()

    url = BASE_URL

    if json_body is not None:
        # POST with JSON body
        response = requests.post(
            f"{url}/books",
            json=json_body,
            timeout=5
        )
    else:
        # GET requests
        if query_params is None:
            url = f"{url}/books"
        else:
            url = f"{url}/books?{&quot;}&quot;".format(
                query_params=requests.compat.urlencode(query_params)
            )

        response = requests.get(url, timeout=5)

    # Check status
    status = response.status_code
    if status != expected_status:
        return False, f"Expected status {expected_status}, got {status}"

    # Check response body
    try:
        resp_json = response.json()
    except json.JSONDecodeError:
        return False, f"Response is not valid JSON: {response.text}"

    if expected_body_contains:
        # Check body contains expected string (case-insensitive for text comparison)
        body_str = resp_json.get('message', str(resp_json)).lower()
        expected_str = expected_body_contains.lower()
        if expected_str not in body_str:
            return False, f"Response body does not contain expected text: {expected_body_contains}"

    if expected_error_message:
        if 'error' in resp_json:
            error_msg = resp_json['error']
            if error_msg != expected_error_message:
                return False, f"Expected error message '{expected_error_message}', got '{error_msg}'"
        else:
            return False, f"Expected error in response but got no error field"

    return True, {}


def test_T1_S1_happy_create():
    """S1 [happy] Create book"""
    return run_test(
        scenario="T1.S1 [happy] Create book",
        expected_status=201,
        json_body={
            "title": "The Great Book",
            "author": "John Doe",
            "isbn": "123456789"
        }
    )


def test_T1_S2_unhappy_invalid_json():
    """S2 [unhappy] Invalid JSON body"""
    return run_test(
        scenario="T1.S2 [unhappy] Invalid JSON body",
        expected_status=400,
        json_body="not json",
        expected_error_message="invalid JSON"
    )


def test_T1_S3_unhappy_missing_title_empty():
    """S3 [unhappy] Missing required title field (empty)"""
    return run_test(
        scenario="T1.S3 [unhappy] Missing required title field (empty)",
        expected_status=400,
        json_body={
            "title": "",
            "author": "John Doe",
            "isbn": "123456"
        },
        expected_error_message="title is empty"
    )


def test_T1_S4_happy_create_happy():
    """T1.S4 [happy] Create_happy"""
    return test_T1_S1_happy_create()  # Same as S1


def test_T1_S5_unhappy_invalid_json():
    """T1.S5 [unhappy] Invalid_JSON"""
    return run_test(
        scenario="T1.S5 [unhappy] Invalid_JSON",
        expected_status=400,
        json_body="not json",
        expected_error_message="invalid JSON"
    )


def test_T1_S6_unhappy_missing_title():
    """T1.S6 [unhappy] Missing_title"""
    return run_test(
        scenario="T1.S6 [unhappy] Missing_title",
        expected_status=400,
        json_body={
            "title": "",
            "author": "John Doe",
            "isbn": "123456"
        },
        expected_error_message="title is empty"
    )


if __name__ == "__main__":
    # Run tests
    tests = [
        test_T1_S1_happy_create,
        test_T1_S2_unhappy_invalid_json,
        test_T1_S3_unhappy_missing_title_empty,
        test_T1_S4_happy_create_happy,
        test_T1_S5_unhappy_invalid_json,
        test_T1_S6_unhappy_missing_title,
    ]

    results = []
    for test in tests:
        success, result = test()
        results.append((test.__name__, success, result))
        print(f"{test.__name__}: {'PASS' if success else 'FAIL'} - {result}")

    # Overall
    all_pass = all(r[1] for r in results)
    print(f"\nOverall: {'PASS' if all_pass else 'FAIL'}")
    if not all_pass:
        for name, success, result in results:
            if not success:
                print(f"  {name}: {result}")
EOF
